// Forge Character Builder — prompt helpers for txt2img / img2img.
// Only the fragment generated by this extension is touched; the existing
// prompt (LoRA, weights, BREAK, ...) is never rewritten.

function computeCharacterBuilderAppend(current, fragment, lastAppended) {
    const text = String(current || "");
    const piece = String(fragment || "").trim();
    if (!piece) {
        return { text: text, changed: false, status: "Nothing to append" };
    }

    const trimmed = text.replace(/\s+$/, "");
    if (lastAppended && piece === lastAppended && trimmed.endsWith(piece)) {
        return { text: text, changed: false, status: "Already appended" };
    }

    if (!trimmed) {
        return { text: piece, changed: true, status: "Prompt appended" };
    }
    const separator = trimmed.endsWith(",") ? " " : ", ";
    return { text: trimmed + separator + piece, changed: true, status: "Prompt appended" };
}

function characterBuilderSwitchTab(tabname) {
    if (tabname === "txt2img" && typeof switch_to_txt2img === "function") {
        switch_to_txt2img();
    } else if (tabname === "img2img" && typeof switch_to_img2img === "function") {
        switch_to_img2img();
    }
}

function appendCharacterBuilderPrompt(text, tabname) {
    const textarea = gradioApp().querySelector(`#${tabname}_prompt textarea`);
    if (!textarea) {
        return `${tabname} prompt box not found`;
    }

    const memory = window.__characterBuilderLastAppended || (window.__characterBuilderLastAppended = {});
    const result = computeCharacterBuilderAppend(textarea.value, text, memory[tabname]);
    if (result.changed) {
        textarea.value = result.text;
        updateInput(textarea);
        memory[tabname] = String(text || "").trim();
    }
    if (result.status !== "Nothing to append") {
        characterBuilderSwitchTab(tabname);
    }
    return result.status;
}

function replaceCharacterBuilderPrompt(text, tabname) {
    const piece = String(text || "").trim();
    if (!piece) {
        return "Nothing to replace with";
    }
    const textarea = gradioApp().querySelector(`#${tabname}_prompt textarea`);
    if (!textarea) {
        return `${tabname} prompt box not found`;
    }
    textarea.value = piece;
    updateInput(textarea);
    const memory = window.__characterBuilderLastAppended || (window.__characterBuilderLastAppended = {});
    memory[tabname] = piece;
    characterBuilderSwitchTab(tabname);
    return "Prompt replaced";
}

// Gallery picks. Gradio only fires Gallery.select when the selected index
// changes, so a slot could not be picked again after paging or Clear. Each
// thumbnail click instead writes "<index>:<nonce>" into the gallery's hidden
// "<gallery id>_pick" textbox, whose change event selects the item in Python.
function characterBuilderPickFromClick(event) {
    const target = event.target;
    const thumb = target && target.closest ? target.closest(".fcb-gallery button.thumbnail-item") : null;
    if (!thumb) {
        return;
    }
    const gallery = thumb.closest(".fcb-gallery");
    if (!gallery || !gallery.id) {
        return;
    }
    const thumbs = Array.from(gallery.querySelectorAll("button.thumbnail-item"));
    const index = thumbs.indexOf(thumb);
    const box = gradioApp().querySelector(`#${gallery.id}_pick textarea, #${gallery.id}_pick input`);
    if (index < 0 || !box) {
        return;
    }
    box.value = `${index}:${Date.now()}`;
    updateInput(box);
}

if (typeof document !== "undefined" && !window.__characterBuilderPickInstalled) {
    window.__characterBuilderPickInstalled = true;
    document.addEventListener("click", characterBuilderPickFromClick, true);
}

// Gallery height. The left column (gallery + pagination) should end level
// with the inspector on the right. Forge's own CSS defeats a pure flexbox
// solution, so measure both columns and give the visible gallery the
// difference, within sane bounds (a tall inspector, e.g. with Advanced open,
// must not turn the gallery into a long empty box).
const CHARACTER_BUILDER_GALLERY_MIN = 420;
const CHARACTER_BUILDER_GALLERY_MAX = 1100;
const CHARACTER_BUILDER_LAYOUTS = [
    [".fcb-workbench", ".fcb-browser"],
    [".fcb-builder", ".fcb-builder-steps"],
];

function computeCharacterBuilderGalleryHeight(current, leftBottom, rightBottom) {
    const wanted = Math.round(current + (rightBottom - leftBottom));
    return Math.max(CHARACTER_BUILDER_GALLERY_MIN, Math.min(CHARACTER_BUILDER_GALLERY_MAX, wanted));
}

function characterBuilderSyncGalleries() {
    const root = gradioApp().querySelector("#tab_forge-character-builder");
    if (!root) {
        return;
    }
    const desktop = window.innerWidth > 900;
    for (const [rowSelector, leftSelector] of CHARACTER_BUILDER_LAYOUTS) {
        for (const row of root.querySelectorAll(rowSelector)) {
            const left = row.querySelector(`:scope > ${leftSelector}`);
            const right = row.querySelector(":scope > .fcb-inspector");
            if (!left || !right || left.offsetParent === null) {
                continue;
            }
            const galleries = Array.from(left.querySelectorAll(".fcb-gallery")).filter((g) => g.offsetParent !== null);
            const gallery = galleries[galleries.length - 1];
            if (!gallery) {
                continue;
            }
            if (!desktop) {
                gallery.style.removeProperty("height");
                continue;
            }
            const current = gallery.getBoundingClientRect().height;
            const height = computeCharacterBuilderGalleryHeight(
                current,
                left.getBoundingClientRect().bottom,
                right.getBoundingClientRect().bottom,
            );
            if (Math.abs(height - current) > 2) {
                gallery.style.setProperty("height", `${height}px`, "important");
            }
        }
    }
}

function characterBuilderInstallGallerySync() {
    let pending = false;
    const schedule = () => {
        if (!pending) {
            pending = true;
            requestAnimationFrame(() => {
                pending = false;
                characterBuilderSyncGalleries();
            });
        }
    };
    const observer = new ResizeObserver(schedule);
    const observed = new WeakSet();
    const attach = () => {
        const root = gradioApp().querySelector("#tab_forge-character-builder");
        if (!root) {
            return false;
        }
        const columns = root.querySelectorAll(".fcb-browser, .fcb-builder-steps, .fcb-inspector");
        for (const column of columns) {
            if (!observed.has(column)) {
                observed.add(column);
                observer.observe(column);
            }
        }
        return columns.length > 0;
    };
    const timer = setInterval(() => {
        if (attach()) {
            clearInterval(timer);
            schedule();
        }
    }, 500);
    window.addEventListener("resize", schedule);
    // Switching tabs shows a different gallery without resizing the columns.
    document.addEventListener("click", () => setTimeout(schedule, 50), true);
}

if (typeof document !== "undefined" && typeof ResizeObserver !== "undefined" && !window.__characterBuilderGallerySyncInstalled) {
    window.__characterBuilderGallerySyncInstalled = true;
    characterBuilderInstallGallerySync();
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { computeCharacterBuilderAppend, computeCharacterBuilderGalleryHeight };
}
